def on_bar(history, account, state):
    # Only completed one-minute bars are visible here.
    if len(history) < 20:
        return None

    fast = sum([bar["close"] for bar in history[-5:]]) / 5
    slow = sum([bar["close"] for bar in history[-20:]]) / 20
    target = 1 if fast > slow else 0

    if target == account["position"]:
        return None

    return {"target": target, "reason": "5 / 20 minute trend"}

def on_bar(history, account, state):
    if len(history) == 1:
        return {"target": 1, "reason": "Enter after the first completed bar"}

    # None keeps the current position.
    return None

def on_bar(history, account, state):
    if len(history) <= 15:
        return None

    opening_high = max([bar["high"] for bar in history[:15]])
    opening_low = min([bar["low"] for bar in history[:15]])
    close = history[-1]["close"]

    if close > opening_high and account["position"] == 0:
        return {"target": 1, "reason": "Above the opening range"}
    if close < opening_low and account["position"] > 0:
        return {"target": 0, "reason": "Below the opening range"}

    return None

